package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's soft-match flags {@code possibleDuplicate} / {@code possibleDuplicateOf}. A
 * hard duplicate (identical {@link OwnerIdentityKey}) has already been rejected with 409 by {@link
 * CheckOwnerIdentityUnique}, so every owner reaching this step is being created. This step flags the
 * weaker overlap: an owner that shares an existing owner's {@code lastName} (compared
 * case-insensitively) and {@code postcode} but carries a <em>different</em> telephone. When such a
 * match exists {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} to the matching
 * owner's id (the lowest id when several match, for determinism); otherwise {@code possibleDuplicate}
 * is false and {@code possibleDuplicateOf} left absent.
 *
 * <p>Runs after {@link BuildOwner} has produced the {@link Owner} and before {@link SaveOwner}
 * persists it, so {@link OwnerRepository#findAll()} returns only the pre-existing owners and the new
 * owner never matches itself. Mutates the entity in place so {@link SaveOwner} stores the values and
 * later reads return them.
 */
public class AssignPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String postcode = owner.getPostcode();
        Integer matchId = null;
        if (postcode != null && !postcode.isBlank()) {
            for (Owner other : ownerRepository.findAll()) {
                if (equalsIgnoreCase(owner.getLastName(), other.getLastName())
                        && postcode.equals(other.getPostcode())
                        && !equals(owner.getTelephone(), other.getTelephone())) {
                    if (matchId == null || (other.getId() != null && other.getId() < matchId)) {
                        matchId = other.getId();
                    }
                }
            }
        }
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return (a == null) ? (b == null) : a.equalsIgnoreCase(b);
    }

    private static boolean equals(String a, String b) {
        return (a == null) ? (b == null) : a.equals(b);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Shared derivation of an owner's {@code identityKey} — the single value that all duplicate
 * detection is now expressed through. The key is
 * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}, where:
 *
 * <ul>
 * <li>{@code normalizedTelephone} is the E.164 form (see {@link TelephoneE164});</li>
 * <li>the email component is the lower-cased email, or empty when none is supplied; and</li>
 * <li>{@code householdId} is the owner's shared household identifier (see {@link Household}), or
 *     empty when the owner belongs to no shared household.</li>
 * </ul>
 *
 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal. Because the telephone
 * is part of the key, two members of the same household (same {@code householdId}) with different
 * telephones have different keys and are both allowed.
 */
public final class OwnerIdentityKey {

    private OwnerIdentityKey() {
    }

    /**
     * Identity key for an incoming create-owner request (after {@link ValidateNewOwner}). The
     * household component is the id the request would be assigned, so the key matches the one the
     * owner will carry once saved.
     */
    public static String forRequest(OwnerFieldsDto request, OwnerRepository ownerRepository) {
        return build(request.getTelephone(), request.getEmail(),
                Household.resolveId(request, ownerRepository));
    }

    /** Identity key for an existing, stored owner. */
    public static String forOwner(Owner owner) {
        return build(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    private static String build(String telephone, String email, String householdId) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
                + (householdId == null ? "" : householdId);
    }

    /** E.164 form when the value can form one, otherwise the raw value so it only matches itself. */
    private static String normalizeTelephone(String telephone) {
        if (telephone == null) {
            return "";
        }
        try {
            return TelephoneE164.normalize(telephone);
        }
        catch (InvalidTelephoneException ex) {
            return telephone;
        }
    }

    /** Lower-cased email, or empty when none is supplied. */
    private static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return "";
        }
        return email.trim().toLowerCase();
    }
}

